using ASimpleMinecraftServer.Models; using System.Diagnostics; using System.IO; using System.Windows; using System.Windows.Controls; namespace ASimpleMinecraftServer.UI.Pages; public partial class PerformanceDashboardView:UserControl { private ServerProfile? _profile; public PerformanceDashboardView(){InitializeComponent();} public void Bind(ServerProfile? p){_profile=p;RefreshButton.IsEnabled=p is not null;SummaryText.Text=p is null?"Select a server first.":$"Performance snapshot for {p.Name}.";if(p is not null)RefreshSnapshot();} private void Refresh_Click(object sender,RoutedEventArgs e)=>RefreshSnapshot(); private void RefreshSnapshot(){if(_profile is null)return;Process? proc=null;try{proc=Process.GetProcessesByName("java").OrderByDescending(x=>x.WorkingSet64).FirstOrDefault();}catch{}MemoryText.Text=proc is null?"Not running":$"{proc.WorkingSet64/1024d/1024d:N0} MB";CpuText.Text=proc is null?"—":$"{proc.TotalProcessorTime.TotalMinutes:N1} min";ThreadsText.Text=proc is null?"—":proc.Threads.Count.ToString();var plugins=Path.Combine(_profile.Folder,"plugins");PluginsText.Text=Directory.Exists(plugins)?Directory.EnumerateFiles(plugins,"*.jar").Count().ToString():"0";var props=ReadProps();var view=props.GetValueOrDefault("view-distance","10");var sim=props.GetValueOrDefault("simulation-distance","10");var players=props.GetValueOrDefault("max-players","20");SettingsText.Text=$"Allocated memory: {_profile.MemoryGb} GB    •    View distance: {view}    •    Simulation distance: {sim}    •    Max players: {players}";GuidanceText.Text=int.TryParse(view,out var v)&&v>12?"High view distance can significantly increase chunk generation and memory pressure. Consider 8–12 for most servers.":"Current view-distance setting is within the common range. Use Spark or Paper timings for authoritative TPS/MSPT measurements.";} private Dictionary<string,string> ReadProps(){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var p=Path.Combine(_profile!.Folder,"server.properties");if(!File.Exists(p))return d;foreach(var l in File.ReadLines(p)){var a=l.Split('=',2);if(a.Length==2)d[a[0].Trim()]=a[1].Trim();}return d;} }